// Protocol constants, error types and shared helpers for MCP revision 2026-07-28.

export const PROTOCOL_VERSION = "2026-07-28";
export const SUPPORTED_VERSIONS: readonly string[] = [PROTOCOL_VERSION];

export const SERVER_INFO = { name: "field-notes", version: "1.0.0" } as const;

export const INSTRUCTIONS =
  "Field Notes stores short notes grouped into notebooks. Use add_note to save a note, read notes://index to see what exists.";

export const META_PROTOCOL_VERSION = "io.modelcontextprotocol/protocolVersion";
export const META_CLIENT_CAPABILITIES = "io.modelcontextprotocol/clientCapabilities";
export const META_SERVER_INFO = "io.modelcontextprotocol/serverInfo";
export const META_SUBSCRIPTION_ID = "io.modelcontextprotocol/subscriptionId";

export const ErrorCode = {
  ParseError: -32700,
  InvalidRequest: -32600,
  MethodNotFound: -32601,
  InvalidParams: -32602,
  InternalError: -32603,
  HeaderMismatch: -32020,
  MissingRequiredClientCapability: -32021,
  UnsupportedProtocolVersion: -32022,
} as const;

export type JsonObject = Record<string, unknown>;
export type RequestId = string | number;

export interface JsonRpcRequest {
  jsonrpc: "2.0";
  id: RequestId;
  method: string;
  params: JsonObject;
}

export interface JsonRpcNotification {
  jsonrpc: "2.0";
  method: string;
  params?: JsonObject;
}

export interface Result extends JsonObject {
  resultType: string;
}

/** A JSON-RPC error, plus the HTTP status the Streamable HTTP transport should use for it. */
export class McpError extends Error {
  readonly code: number;
  readonly data: unknown;
  readonly httpStatus: number;

  constructor(code: number, message: string, data?: unknown, httpStatus = 200) {
    super(message);
    this.code = code;
    this.data = data;
    this.httpStatus = httpStatus;
  }

  toJson(): JsonObject {
    const error: JsonObject = { code: this.code, message: this.message };
    if (this.data !== undefined) error.data = this.data;
    return error;
  }
}

export function isObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function invalidParams(message: string, data?: unknown, httpStatus = 200): McpError {
  return new McpError(ErrorCode.InvalidParams, message, data, httpStatus);
}

export function headerMismatch(message: string): McpError {
  return new McpError(ErrorCode.HeaderMismatch, `Header mismatch: ${message}`, undefined, 400);
}

export function unsupportedVersion(requested: string): McpError {
  return new McpError(
    ErrorCode.UnsupportedProtocolVersion,
    `Unsupported protocol version: ${requested}. Supported versions: ${SUPPORTED_VERSIONS.join(", ")}`,
    { supported: [...SUPPORTED_VERSIONS], requested },
    400,
  );
}

/** Adds the fields every successful result carries. */
export function complete(body: JsonObject): Result {
  return { ...body, resultType: "complete", _meta: serverMeta() };
}

export function inputRequired(body: { inputRequests?: JsonObject; requestState?: string }): Result {
  return { ...body, resultType: "input_required", _meta: serverMeta() };
}

export function serverMeta(): JsonObject {
