// End-to-end tests: start the built server and exercise it over HTTP.

import assert from "node:assert/strict";
import { after, before, describe, test } from "node:test";
import {
  call,
  listen,
  post,
  PROTOCOL_VERSION,
  readResponse,
  requestMeta,
  SseReader,
  standardHeaders,
  startServer,
  type RunningServer,
} from "./helpers.ts";

const FORM = { elicitation: { form: {} } };
const SERVER_INFO = { name: "field-notes", version: "1.0.0" };

let server: RunningServer;
let url: string;

before(async () => {
  server = await startServer();
  url = server.url;
});

after(async () => {
  await server?.stop();
});

function text(result: any): string {
  return result.content.map((c: any) => c.text).join("");
}

describe("transport and protocol envelope", () => {
  test("server/discover advertises version, capabilities, identity and instructions", async () => {
    const { status, body, headers } = await call(url, "server/discover");
    assert.equal(status, 200);
    assert.match(headers.get("content-type")!, /^application\/json/);
    const r = body.result;
    assert.equal(r.resultType, "complete");
    assert.deepEqual(r.supportedVersions, [PROTOCOL_VERSION]);
    assert.deepEqual(r.capabilities, { tools: {}, resources: { subscribe: true }, prompts: {} });
    assert.deepEqual(r._meta["io.modelcontextprotocol/serverInfo"], SERVER_INFO);
    assert.equal(
      r.instructions,
      "Field Notes stores short notes grouped into notebooks. Use add_note to save a note, read notes://index to see what exists.",
    );
    assert.equal(r.ttlMs, 300000);
    assert.equal(r.cacheScope, "public");
  });

  test("every result identifies the server", async () => {
    const { body } = await call(url, "tools/list");
    assert.deepEqual(body.result._meta["io.modelcontextprotocol/serverInfo"], SERVER_INFO);
  });

  test("missing _meta is invalid params with 400", async () => {
    const res = await post(url, { jsonrpc: "2.0", id: 1, method: "tools/list", params: {} }, standardHeaders("tools/list", {}));
    const { status, body } = await readResponse(res);
    assert.equal(status, 400);
    assert.equal(body.id, 1);
    assert.equal(body.error.code, -32602);
  });

  test("missing clientCapabilities is invalid params with 400", async () => {
    const params = { _meta: { "io.modelcontextprotocol/protocolVersion": PROTOCOL_VERSION } };
    const res = await post(url, { jsonrpc: "2.0", id: 2, method: "tools/list", params }, standardHeaders("tools/list", params));
    const { status, body } = await readResponse(res);
    assert.equal(status, 400);
    assert.equal(body.error.code, -32602);
  });

  test("unsupported protocol version lists supported versions", async () => {
    const params = { _meta: { ...requestMeta(), "io.modelcontextprotocol/protocolVersion": "2025-11-25" } };
    const headers = { ...standardHeaders("tools/list", params), "MCP-Protocol-Version": "2025-11-25" };
    const { status, body } = await readResponse(await post(url, { jsonrpc: "2.0", id: 3, method: "tools/list", params }, headers));
    assert.equal(status, 400);
    assert.equal(body.error.code, -32022);
    assert.deepEqual(body.error.data, { supported: [PROTOCOL_VERSION], requested: "2025-11-25" });
  });

  test("legacy initialize is rejected naming the supported versions", async () => {
    const res = await post(
      url,
      { jsonrpc: "2.0", id: 0, method: "initialize", params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "old", version: "1" } } },
      { "Content-Type": "application/json", Accept: "application/json, text/event-stream" },
    );
    const { status, body } = await readResponse(res);
    assert.equal(status, 400);
    assert.equal(body.error.code, -32022);
    assert.deepEqual(body.error.data.supported, [PROTOCOL_VERSION]);
  });

  test("missing MCP-Protocol-Version header is a header mismatch", async () => {
    const { status, body } = await call(url, "tools/list", {}, { headers: { "MCP-Protocol-Version": null } });
    assert.equal(status, 400);
    assert.equal(body.error.code, -32020);
  });

  test("MCP-Protocol-Version header must match _meta", async () => {
    const { status, body } = await call(url, "tools/list", {}, { headers: { "MCP-Protocol-Version": "2099-01-01" } });
    assert.equal(status, 400);
    assert.equal(body.error.code, -32020);
  });

  test("Mcp-Method header is required and must match", async () => {
    let r = await call(url, "tools/list", {}, { headers: { "Mcp-Method": null } });
    assert.equal(r.status, 400);
    assert.equal(r.body.error.code, -32020);
    r = await call(url, "tools/list", {}, { headers: { "Mcp-Method": "prompts/list" } });
    assert.equal(r.status, 400);
    assert.equal(r.body.error.code, -32020);
  });

  test("Mcp-Name header is required and must match, Base64 sentinel is decoded", async () => {
    let r = await call(url, "resources/read", { uri: "notes://index" }, { headers: { "Mcp-Name": null } });
    assert.equal(r.status, 400);
    assert.equal(r.body.error.code, -32020);
    r = await call(url, "resources/read", { uri: "notes://index" }, { headers: { "Mcp-Name": "notes://notes/n1" } });
    assert.equal(r.status, 400);
    assert.equal(r.body.error.code, -32020);
    const encoded = `=?base64?${Buffer.from("notes://index").toString("base64")}?=`;
    r = await call(url, "resources/read", { uri: "notes://index" }, { headers: { "Mcp-Name": encoded } });
    assert.equal(r.status, 200);
    assert.equal(r.body.result.resultType, "complete");
    r = await call(url, "resources/read", { uri: "notes://index" }, { headers: { "Mcp-Name": "=?base64?!!!?=" } });
    assert.equal(r.status, 400);
    assert.equal(r.body.error.code, -32020);
  });

  test("unknown method is 404 with -32601", async () => {
    const { status, body } = await call(url, "resources/subscribe", { uri: "notes://index" });
    assert.equal(status, 404);
    assert.equal(body.error.code, -32601);
  });

  test("invalid JSON is a parse error", async () => {
    const res = await post(url, "{not json", standardHeaders("tools/list", {}));
    const { status, body } = await readResponse(res);
    assert.equal(status, 400);
    assert.equal(body.error.code, -32700);
  });

  test("batches and responses are invalid requests", async () => {
    let res = await post(url, [{ jsonrpc: "2.0", id: 1, method: "tools/list" }], standardHeaders("tools/list", {}));
    assert.equal(res.status, 400);
    assert.equal((await res.json()).error.code, -32600);
    res = await post(url, { jsonrpc: "2.0", id: 1, result: {} }, standardHeaders("tools/list", {}));
    assert.equal(res.status, 400);
    assert.equal((await res.json()).error.code, -32600);
  });

  test("notifications are accepted with 202 and no body", async () => {
    const res = await post(
      url,
      { jsonrpc: "2.0", method: "notifications/cancelled", params: { requestId: 99 } },
      { "Content-Type": "application/json", Accept: "application/json, text/event-stream" },
    );
    assert.equal(res.status, 202);
    assert.equal(await res.text(), "");
  });

  test("GET and DELETE are 405, other paths 404", async () => {
    assert.equal((await fetch(url)).status, 405);
    assert.equal((await fetch(url, { method: "DELETE" })).status, 405);
    const other = url.replace(/\/mcp$/, "/other");
    assert.equal((await post(other, {}, standardHeaders("tools/list", {}))).status, 404);
  });

  test("browser origins other than localhost:PORT are forbidden", async () => {
    let r = await call(url, "tools/list", {}, { headers: { Origin: "http://evil.example" } });
    assert.equal(r.status, 403);
    r = await call(url, "tools/list", {}, { headers: { Origin: `http://localhost:${server.port + 1}` } });
    assert.equal(r.status, 403);
    r = await call(url, "tools/list", {}, { headers: { Origin: `http://localhost:${server.port}` } });
    assert.equal(r.status, 200);
    r = await call(url, "tools/list", {}, { headers: { Origin: `http://127.0.0.1:${server.port}` } });
    assert.equal(r.status, 200);
  });

  test("Mcp-Session-Id is ignored and never minted", async () => {
    const r = await call(url, "tools/list", {}, { headers: { "Mcp-Session-Id": "abc" } });
    assert.equal(r.status, 200);
    assert.equal(r.headers.get("mcp-session-id"), null);
  });
});

describe("tools", () => {
  test("tools/list returns the three tools alphabetically, cacheable", async () => {
    const { body } = await call(url, "tools/list");
    const r = body.result;
    assert.deepEqual(r.tools.map((t: any) => t.name), ["add_note", "delete_note", "reindex"]);
    assert.equal(r.ttlMs, 300000);
    assert.equal(r.cacheScope, "public");
    assert.equal(r.nextCursor, undefined);
    const add = r.tools[0];
    assert.equal(add.inputSchema.type, "object");
    assert.equal(add.inputSchema.properties.notebook["x-mcp-header"], "Notebook");
    assert.deepEqual([...add.inputSchema.required].sort(), ["body", "notebook", "title"]);
    assert.equal(add.outputSchema.type, "object");
    assert.deepEqual([...add.outputSchema.required].sort(), ["id", "notebook", "uri", "wordCount"]);
  });

  test("an unknown cursor is invalid params", async () => {
    const { body } = await call(url, "tools/list", { cursor: "bogus" });
    assert.equal(body.error.code, -32602);
  });

  test("unknown tool is a protocol error", async () => {
    const { body } = await call(url, "tools/call", { name: "nope", arguments: {} });
    assert.equal(body.error.code, -32602);
  });

  test("add_note returns structured output and a text copy", async () => {
    const { status, body } = await call(url, "tools/call", {
      name: "add_note",
      arguments: { notebook: "work", title: "Plan", body: "  ship   it\tnow\n" },
    });
    assert.equal(status, 200);
    const r = body.result;
    assert.equal(r.resultType, "complete");
    assert.notEqual(r.isError, true);
    assert.match(r.structuredContent.id, /^n\d+$/);
    assert.deepEqual(r.structuredContent, {
      id: r.structuredContent.id,
      uri: `notes://notes/${r.structuredContent.id}`,
      notebook: "work",
      wordCount: 3,
    });
    assert.deepEqual(JSON.parse(text(r)), r.structuredContent);

    const read = await call(url, "resources/read", { uri: r.structuredContent.uri });
    assert.equal(read.body.result.contents[0].text, "# Plan\n\nship   it\tnow\n".replace("ship", "  ship").replace("now\n", "now\n\n"));
  });

  test("add_note requires the Mcp-Param-Notebook header to match the body", async () => {
    const params = { name: "add_note", arguments: { notebook: "work", title: "T", body: "" } };
    let r = await call(url, "tools/call", params, { headers: { "Mcp-Param-Notebook": null } });
    assert.equal(r.status, 400);
    assert.equal(r.body.error.code, -32020);
    r = await call(url, "tools/call", params, { headers: { "Mcp-Param-Notebook": "personal" } });
    assert.equal(r.status, 400);
    assert.equal(r.body.error.code, -32020);
    const encoded = `=?base64?${Buffer.from("work").toString("base64")}?=`;
    r = await call(url, "tools/call", params, { headers: { "mcp-param-notebook": encoded } });
    assert.equal(r.status, 200);
    assert.notEqual(r.body.result.isError, true);
  });

  test("add_note argument problems are tool execution errors", async () => {
    const cases = [
      { notebook: "work", body: "x" },
      { notebook: "work", title: "", body: "x" },
      { notebook: "bad name!", title: "t", body: "x" },
      { notebook: "work", title: "x".repeat(201), body: "x" },
      { notebook: "work", title: 5, body: "x" },
      { notebook: "work", title: "t" },
      { notebook: "x".repeat(65), title: "t", body: "" },
    ];
    for (const args of cases) {
      const { status, body } = await call(url, "tools/call", { name: "add_note", arguments: args });
      assert.equal(status, 200, JSON.stringify(args));
      assert.equal(body.result.isError, true, JSON.stringify(args));
      assert.ok(text(body.result).length > 0);
    }
    const ok = await call(url, "tools/call", {
      name: "add_note",
      arguments: { notebook: "x".repeat(64), title: "y".repeat(200), body: "" },
    });
    assert.notEqual(ok.body.result.isError, true);
    assert.equal(ok.body.result.structuredContent.wordCount, 0);
  });

  test("reindex without a progress token returns plain JSON", async () => {
    const { headers, body } = await call(url, "tools/call", { name: "reindex", arguments: { steps: 2, delayMs: 0 } });
    assert.match(headers.get("content-type")!, /^application\/json/);
    assert.equal(text(body.result), "Reindex complete: 2 steps");
  });

  test("reindex streams progress over SSE when asked", async () => {
    const { headers, body, notifications } = await call(
      url,
      "tools/call",
      { name: "reindex", arguments: { steps: 3, delayMs: 10 } },
      { meta: { progressToken: "tok-1" } },
    );
    assert.match(headers.get("content-type")!, /^text\/event-stream/);
    assert.deepEqual(
      notifications.map((n) => [n.method, n.params.progressToken, n.params.progress, n.params.total, n.params.message]),
      [
        ["notifications/progress", "tok-1", 1, 3, "Indexed 1/3"],
        ["notifications/progress", "tok-1", 2, 3, "Indexed 2/3"],
        ["notifications/progress", "tok-1", 3, 3, "Indexed 3/3"],
      ],
    );
    assert.equal(text(body.result), "Reindex complete: 3 steps");
  });

  test("reindex defaults to 5 steps", async () => {
    const { notifications, body } = await call(
      url,
      "tools/call",
      { name: "reindex", arguments: { delayMs: 0 } },
      { meta: { progressToken: 7 } },
    );
    assert.equal(notifications.length, 5);
    assert.equal(text(body.result), "Reindex complete: 5 steps");
  });

  test("reindex out-of-range arguments are tool errors", async () => {
    for (const args of [{ steps: 0 }, { steps: 21 }, { steps: 2.5 }, { delayMs: -1 }, { delayMs: 1001 }, { steps: "3" }]) {
      const { body } = await call(url, "tools/call", { name: "reindex", arguments: args });
      assert.equal(body.result.isError, true, JSON.stringify(args));
    }
  });

  test("reindex survives a client that goes away mid-stream", async () => {
    const controller = new AbortController();
    const params = { name: "reindex", arguments: { steps: 20, delayMs: 50 } };
    const res = await post(
      url,
      { jsonrpc: "2.0", id: "cancel-me", method: "tools/call", params: { ...params, _meta: requestMeta({}, { progressToken: "c" }) } },
      standardHeaders("tools/call", params),
      controller.signal,
    );
    const reader = new SseReader(res);
    const first = await reader.next();
    assert.equal(first.params.progress, 1);
    controller.abort();
    await reader.cancel();
    // The server keeps serving other requests.
    const { status } = await call(url, "tools/list");
    assert.equal(status, 200);
  });
});

describe("delete_note (multi round-trip confirmation)", () => {
  async function newNote(title: string): Promise<string> {
    const { body } = await call(url, "tools/call", { name: "add_note", arguments: { notebook: "tmp", title, body: "b" } });
    return body.result.structuredContent.id;
  }

  async function exists(id: string): Promise<boolean> {
    const { body } = await call(url, "resources/read", { uri: `notes://notes/${id}` });
    return body.result !== undefined;
  }

  test("unknown note is a tool error", async () => {
    const { body } = await call(url, "tools/call", { name: "delete_note", arguments: { id: "n9999" } }, { capabilities: FORM });
    assert.equal(body.result.isError, true);
    assert.equal(text(body.result), "Note n9999 not found");
  });

  test("clients without form elicitation get MissingRequiredClientCapability", async () => {
    const id = await newNote("keep me");
    for (const capabilities of [{}, { elicitation: { url: {} } }]) {
      const { status, body } = await call(url, "tools/call", { name: "delete_note", arguments: { id } }, { capabilities });
      assert.equal(status, 400);
      assert.equal(body.error.code, -32021);
      assert.ok(body.error.data.requiredCapabilities.elicitation);
    }
    assert.ok(await exists(id));
  });

  test("asks for confirmation, then deletes on confirm: true", async () => {
    const id = await newNote("Doomed");
    const first = await call(url, "tools/call", { name: "delete_note", arguments: { id } }, { capabilities: { elicitation: {} } });
    const r = first.body.result;
    assert.equal(r.resultType, "input_required");
    assert.equal(typeof r.requestState, "string");
    const [key, request] = Object.entries(r.inputRequests as Record<string, any>)[0]!;
    assert.equal(request.method, "elicitation/create");
    assert.equal(request.params.mode, "form");
    assert.equal(request.params.message, 'Delete note "Doomed"?');
    assert.deepEqual(request.params.requestedSchema.required, ["confirm"]);
    assert.equal(request.params.requestedSchema.properties.confirm.type, "boolean");
    assert.equal(r.ttlMs, undefined);
    assert.ok(await exists(id));

    const retry = await call(
      url,
      "tools/call",
      {
        name: "delete_note",
        arguments: { id },
        inputResponses: { [key]: { action: "accept", content: { confirm: true } } },
        requestState: r.requestState,
      },
      { capabilities: FORM },
    );
    assert.equal(retry.body.result.resultType, "complete");
    assert.equal(text(retry.body.result), `Deleted note ${id}`);
    assert.equal(await exists(id), false);

    // Replaying the same confirmation cannot delete anything else.
    const replay = await call(
      url,
      "tools/call",
      { name: "delete_note", arguments: { id }, inputResponses: { [key]: { action: "accept", content: { confirm: true } } }, requestState: r.requestState },
      { capabilities: FORM },
    );
    assert.equal(text(replay.body.result), `Note ${id} not found`);
  });

  test("decline, cancel and confirm: false leave the note alone", async () => {
    const id = await newNote("Survivor");
    for (const answer of [{ action: "decline" }, { action: "cancel" }, { action: "accept", content: { confirm: false } }]) {
      const first = await call(url, "tools/call", { name: "delete_note", arguments: { id } }, { capabilities: FORM });
      const { inputRequests, requestState } = first.body.result;
      const key = Object.keys(inputRequests)[0]!;
      const retry = await call(
        url,
        "tools/call",
        { name: "delete_note", arguments: { id }, inputResponses: { [key]: answer }, requestState },
        { capabilities: FORM },
      );
      assert.equal(retry.body.result.isError, undefined === retry.body.result.isError ? undefined : false);
      assert.equal(text(retry.body.result), "Deletion cancelled", JSON.stringify(answer));
    }
    assert.ok(await exists(id));
  });

  test("confirmation for one note cannot delete another, nor be forged", async () => {
    const a = await newNote("A");
    const b = await newNote("B");
    const first = await call(url, "tools/call", { name: "delete_note", arguments: { id: a } }, { capabilities: FORM });
    const { inputRequests, requestState } = first.body.result;
    const key = Object.keys(inputRequests)[0]!;
    const yes = { [key]: { action: "accept", content: { confirm: true } } };

    // Reusing A's confirmation for B.
    let r = await call(url, "tools/call", { name: "delete_note", arguments: { id: b }, inputResponses: yes, requestState }, { capabilities: FORM });
    assert.ok(r.body.error || r.body.result.resultType !== "complete" || !/Deleted/.test(text(r.body.result)));

    // Tampered state.
    const [payload, mac] = requestState.split(".");
    const forged = Buffer.from(JSON.stringify({ ...JSON.parse(Buffer.from(payload, "base64url").toString()), noteId: b })).toString("base64url");
    r = await call(url, "tools/call", { name: "delete_note", arguments: { id: b }, inputResponses: yes, requestState: `${forged}.${mac}` }, { capabilities: FORM });
    assert.equal(r.body.error?.code, -32602);
    r = await call(url, "tools/call", { name: "delete_note", arguments: { id: b }, inputResponses: yes, requestState: "garbage" }, { capabilities: FORM });
    assert.equal(r.body.error?.code, -32602);

    // Answers without any server-issued state just trigger a fresh confirmation.
    r = await call(url, "tools/call", { name: "delete_note", arguments: { id: b }, inputResponses: yes }, { capabilities: FORM });
    assert.equal(r.body.result.resultType, "input_required");

    assert.ok(await exists(a));
    assert.ok(await exists(b));
  });

  test("a retry without the answer asks again", async () => {
    const id = await newNote("Again");
    const first = await call(url, "tools/call", { name: "delete_note", arguments: { id } }, { capabilities: FORM });
    const r = await call(
      url,
      "tools/call",
      { name: "delete_note", arguments: { id }, inputResponses: {}, requestState: first.body.result.requestState },
      { capabilities: FORM },
    );
    assert.equal(r.body.result.resultType, "input_required");
    assert.ok(await exists(id));
  });
});

describe("resources", () => {
  test("resources/list has only the index", async () => {
    const { body } = await call(url, "resources/list");
    assert.deepEqual(body.result.resources, [
      { uri: "notes://index", name: "index", title: "All notes", mimeType: "application/json" },
    ]);
    assert.equal(body.result.ttlMs, 300000);
    assert.equal(body.result.cacheScope, "public");
  });

  test("resources/templates/list has the note template", async () => {
    const { body } = await call(url, "resources/templates/list");
    assert.deepEqual(body.result.resourceTemplates, [
      { uriTemplate: "notes://notes/{id}", name: "note", title: "A single note", mimeType: "text/markdown" },
    ]);
    assert.equal(body.result.ttlMs, 300000);
    assert.equal(body.result.cacheScope, "public");
  });

  test("reading n1 renders markdown, private and never fresh", async () => {
    const { body } = await call(url, "resources/read", { uri: "notes://notes/n1" });
    assert.deepEqual(body.result.contents, [
      { uri: "notes://notes/n1", mimeType: "text/markdown", text: "# Standup\n\nDiscussed the release schedule and blockers.\n" },
    ]);
    assert.equal(body.result.ttlMs, 0);
    assert.equal(body.result.cacheScope, "private");
  });

  test("the index lists notes in numeric id order", async () => {
    const { body } = await call(url, "resources/read", { uri: "notes://index" });
    const [content] = body.result.contents;
    assert.equal(content.mimeType, "application/json");
    const index = JSON.parse(content.text);
    assert.deepEqual(index.slice(0, 3), [
      { id: "n1", notebook: "work", title: "Standup" },
      { id: "n2", notebook: "work", title: "Retro actions" },
      { id: "n3", notebook: "personal", title: "Groceries" },
    ]);
    const numbers = index.map((n: any) => Number(n.id.slice(1)));
    assert.deepEqual(numbers, [...numbers].sort((a, b) => a - b));
    assert.ok(index.length >= 10, "enough notes were created by earlier tests to check n10 ordering");
    assert.equal(body.result.cacheScope, "private");
  });

  test("missing resources are -32602", async () => {
    for (const uri of ["notes://notes/n424242", "notes://nope", "file:///etc/passwd"]) {
      const { body } = await call(url, "resources/read", { uri });
      assert.equal(body.error.code, -32602, uri);
      assert.equal(body.error.data.uri, uri);
    }
  });
});

describe("prompts", () => {
  test("prompts/list", async () => {
    const { body } = await call(url, "prompts/list");
    assert.equal(body.result.prompts.length, 1);
    const [p] = body.result.prompts;
    assert.equal(p.name, "summarize_notebook");
    assert.deepEqual(
      p.arguments.map((a: any) => [a.name, a.required]),
      [["notebook", true], ["style", false]],
    );
    assert.equal(body.result.ttlMs, 300000);
    assert.equal(body.result.cacheScope, "public");
  });

  test("brief summary embeds the notebook's notes", async () => {
    const { body } = await call(url, "prompts/get", { name: "summarize_notebook", arguments: { notebook: "personal" } });
    assert.equal(body.result.resultType, "complete");
    assert.deepEqual(body.result.messages, [
      { role: "user", content: { type: "text", text: 'Summarize the notes in the "personal" notebook in two sentences.' } },
      {
        role: "user",
        content: {
          type: "resource",
          resource: { uri: "notes://notes/n3", mimeType: "text/markdown", text: "# Groceries\n\nEggs, flour, coffee.\n" },
        },
      },
    ]);
  });

  test("detailed style and empty notebooks", async () => {
    let { body } = await call(url, "prompts/get", { name: "summarize_notebook", arguments: { notebook: "work", style: "detailed" } });
    assert.equal(
      body.result.messages[0].content.text,
      'Summarize the notes in the "work" notebook in detail, one paragraph per note.',
    );
    assert.deepEqual(body.result.messages.slice(1, 3).map((m: any) => m.content.resource.uri), ["notes://notes/n1", "notes://notes/n2"]);
    ({ body } = await call(url, "prompts/get", { name: "summarize_notebook", arguments: { notebook: "empty-one" } }));
    assert.equal(body.result.messages.length, 1);
  });

  test("bad arguments are invalid params", async () => {
    for (const args of [{}, { notebook: "work", style: "haiku" }, undefined]) {
      const { body } = await call(url, "prompts/get", { name: "summarize_notebook", arguments: args });
      assert.equal(body.error.code, -32602, JSON.stringify(args));
    }
    const { body } = await call(url, "prompts/get", { name: "nope", arguments: {} });
    assert.equal(body.error.code, -32602);
  });
});

describe("subscriptions/listen", () => {
  test("acknowledges, then notifies only watchers of changed URIs", async () => {
    const all = await listen(url, { resourceSubscriptions: ["notes://index", "notes://notes/n2", "https://elsewhere"], toolsListChanged: true }, "sub-all");
    assert.equal(all.res.status, 200);
    assert.match(all.res.headers.get("content-type")!, /^text\/event-stream/);
    const ack = await all.reader.next();
    assert.equal(ack.method, "notifications/subscriptions/acknowledged");
    assert.equal(ack.params._meta["io.modelcontextprotocol/subscriptionId"], "sub-all");
    assert.deepEqual(ack.params.notifications, { resourceSubscriptions: ["notes://index", "notes://notes/n2"] });

    const other = await listen(url, { resourceSubscriptions: ["notes://notes/n1"] }, 42);
    const ack2 = await other.reader.next();
    assert.equal(ack2.params._meta["io.modelcontextprotocol/subscriptionId"], 42);

    // Adding a note updates the index only.
    await call(url, "tools/call", { name: "add_note", arguments: { notebook: "work", title: "New", body: "" } });
    const added = await all.reader.next();
    assert.equal(added.method, "notifications/resources/updated");
    assert.equal(added.params.uri, "notes://index");
    assert.equal(added.params._meta["io.modelcontextprotocol/subscriptionId"], "sub-all");
    assert.ok(await other.reader.quiet(300), "watcher of n1 must not hear about the index");

    // Deleting n2 updates the index and n2.
    const ask = await call(url, "tools/call", { name: "delete_note", arguments: { id: "n2" } }, { capabilities: FORM });
    const key = Object.keys(ask.body.result.inputRequests)[0]!;
    const done = await call(
      url,
      "tools/call",
      {
        name: "delete_note",
        arguments: { id: "n2" },
        inputResponses: { [key]: { action: "accept", content: { confirm: true } } },
        requestState: ask.body.result.requestState,
      },
      { capabilities: FORM },
    );
    assert.equal(text(done.body.result), "Deleted note n2");
    const uris = [(await all.reader.next()).params.uri, (await all.reader.next()).params.uri].sort();
    assert.deepEqual(uris, ["notes://index", "notes://notes/n2"]);
    assert.ok(await other.reader.quiet(300));

    await all.reader.cancel();
    await other.reader.cancel();
  });

  test("a malformed filter is invalid params", async () => {
    const { res } = await listen(url, { resourceSubscriptions: "notes://index" } as any, 5);
    const { body } = await readResponse(res);
    assert.equal(body.error.code, -32602);
  });

  test("server shutdown ends subscriptions gracefully", async () => {
    const own = await startServer();
    const sub = await listen(own.url, { resourceSubscriptions: ["notes://index"] }, "bye");
    await sub.reader.next();
    own.child.kill("SIGTERM");
    const final = await sub.reader.next();
    assert.equal(final.id, "bye");
    assert.equal(final.result.resultType, "complete");
    assert.equal(final.result._meta["io.modelcontextprotocol/subscriptionId"], "bye");
    assert.equal(await sub.reader.next(), undefined);
    await own.stop();
  });
});

