    assert.equal(body.result.cacheScope, "public");
  });

  test("reading n1 renders markdown, private and never fresh", async () => {
    const { body } = await call(url, "resources/read", { uri: "notes://notes/n1" });
    assert.deepEqual(body.result.contents, [
      { uri: "notes://notes/n1", mimeType: "text/markdown", text: "# Standup\n\nDiscussed the release schedule and blockers.\n" },
    ]);
    assert.equal(body.result.ttlMs, 0);
    assert.equal(body.result.cacheScope, "private");
  });

  test("the index lists notes in numeric id order", async () => {
    const { body } = await call(url, "resources/read", { uri: "notes://index" });
    const [content] = body.result.contents;
    assert.equal(content.mimeType, "application/json");
    const index = JSON.parse(content.text);
    assert.deepEqual(index.slice(0, 3), [
      { id: "n1", notebook: "work", title: "Standup" },
      { id: "n2", notebook: "work", title: "Retro actions" },
      { id: "n3", notebook: "personal", title: "Groceries" },
    ]);
    const numbers = index.map((n: any) => Number(n.id.slice(1)));
    assert.deepEqual(numbers, [...numbers].sort((a, b) => a - b));
    assert.ok(index.length >= 10, "enough notes were created by earlier tests to check n10 ordering");
    assert.equal(body.result.cacheScope, "private");
  });

  test("missing resources are -32602", async () => {
    for (const uri of ["notes://notes/n424242", "notes://nope", "file:///etc/passwd"]) {
      const { body } = await call(url, "resources/read", { uri });
      assert.equal(body.error.code, -32602, uri);
      assert.equal(body.error.data.uri, uri);
    }
  });
});

describe("prompts", () => {
  test("prompts/list", async () => {
    const { body } = await call(url, "prompts/list");
    assert.equal(body.result.prompts.length, 1);
    const [p] = body.result.prompts;
    assert.equal(p.name, "summarize_notebook");
    assert.deepEqual(
      p.arguments.map((a: any) => [a.name, a.required]),
      [["notebook", true], ["style", false]],
    );
    assert.equal(body.result.ttlMs, 300000);
    assert.equal(body.result.cacheScope, "public");
  });

  test("brief summary embeds the notebook's notes", async () => {
    const { body } = await call(url, "prompts/get", { name: "summarize_notebook", arguments: { notebook: "personal" } });
    assert.equal(body.result.resultType, "complete");
    assert.deepEqual(body.result.messages, [
      { role: "user", content: { type: "text", text: 'Summarize the notes in the "personal" notebook in two sentences.' } },
      {
        role: "user",
        content: {
          type: "resource",
          resource: { uri: "notes://notes/n3", mimeType: "text/markdown", text: "# Groceries\n\nEggs, flour, coffee.\n" },
        },
      },
    ]);
  });

  test("detailed style and empty notebooks", async () => {
    let { body } = await call(url, "prompts/get", { name: "summarize_notebook", arguments: { notebook: "work", style: "detailed" } });
    assert.equal(
      body.result.messages[0].content.text,
      'Summarize the notes in the "work" notebook in detail, one paragraph per note.',
    );
    assert.deepEqual(body.result.messages.slice(1, 3).map((m: any) => m.content.resource.uri), ["notes://notes/n1", "notes://notes/n2"]);
    ({ body } = await call(url, "prompts/get", { name: "summarize_notebook", arguments: { notebook: "empty-one" } }));
    assert.equal(body.result.messages.length, 1);
  });

  test("bad arguments are invalid params", async () => {
    for (const args of [{}, { notebook: "work", style: "haiku" }, undefined]) {
      const { body } = await call(url, "prompts/get", { name: "summarize_notebook", arguments: args });
      assert.equal(body.error.code, -32602, JSON.stringify(args));
