// Test helpers: start the built server as a child process and talk MCP over HTTP.

import { spawn, type ChildProcess } from "node:child_process";
import { fileURLToPath } from "node:url";

export const PROTOCOL_VERSION = "2026-07-28";
const SERVER_ENTRY = fileURLToPath(new URL("../dist/server.js", import.meta.url));

export interface RunningServer {
  url: string;
  port: number;
  child: ChildProcess;
  stop(): Promise<void>;
}

/** Starts `node dist/server.js` on a random port (run `npm run build` first). */
export function startServer(): Promise<RunningServer> {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [SERVER_ENTRY], {
      env: { ...process.env, PORT: "0" },
      stdio: ["ignore", "pipe", "inherit"],
    });
    let output = "";
    const timer = setTimeout(() => reject(new Error(`server did not start: ${output}`)), 10_000);
    child.stdout!.setEncoding("utf8");
    child.stdout!.on("data", (chunk: string) => {
      output += chunk;
      const match = /listening on (http:\/\/127\.0\.0\.1:(\d+)\/mcp)/.exec(output);
      if (!match) return;
      clearTimeout(timer);
      resolve({
        url: match[1]!,
        port: Number(match[2]),
        child,
        stop: () =>
          new Promise<void>((done) => {
            if (child.exitCode !== null) return done();
            child.once("exit", () => done());
            child.kill("SIGTERM");
          }),
      });
    });
    child.once("exit", (code) => reject(new Error(`server exited early (${code}): ${output}`)));
  });
}

export interface CallOptions {
  id?: string | number;
  capabilities?: Record<string, unknown>;
  meta?: Record<string, unknown>;
  /** Extra/override headers; a value of `null` removes a default header. */
  headers?: Record<string, string | null>;
  signal?: AbortSignal;
}

export interface RpcResponse {
  status: number;
  headers: Headers;
  /** The final JSON-RPC response. */
  body: any;
  /** Notifications received before the final response (SSE only). */
  notifications: any[];
}

let nextId = 1;

export function requestMeta(capabilities: Record<string, unknown> = {}, extra: Record<string, unknown> = {}) {
  return {
    "io.modelcontextprotocol/protocolVersion": PROTOCOL_VERSION,
    "io.modelcontextprotocol/clientInfo": { name: "field-notes-tests", version: "0.0.0" },
    "io.modelcontextprotocol/clientCapabilities": capabilities,
    ...extra,
  };
}

/** Builds the standard headers a conforming client sends for this request. */
export function standardHeaders(method: string, params: Record<string, any>): Record<string, string> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    "MCP-Protocol-Version": PROTOCOL_VERSION,
    "Mcp-Method": method,
  };
  if (method === "tools/call" || method === "prompts/get") headers["Mcp-Name"] = encodeHeader(params.name);
  if (method === "resources/read") headers["Mcp-Name"] = encodeHeader(params.uri);
  if (method === "tools/call" && params.name === "add_note" && typeof params.arguments?.notebook === "string") {
    headers["Mcp-Param-Notebook"] = encodeHeader(params.arguments.notebook);
  }
  return headers;
}

export function encodeHeader(value: string): string {
  const plain = /^[\x21-\x7e]([\x20-\x7e]*[\x21-\x7e])?$/.test(value);
  const sentinel = value.startsWith("=?base64?") && value.endsWith("?=");
  return plain && !sentinel ? value : `=?base64?${Buffer.from(value, "utf8").toString("base64")}?=`;
}

export async function post(url: string, body: unknown, headers: Record<string, string>, signal?: AbortSignal) {
  return fetch(url, {
    method: "POST",
    headers,
    body: typeof body === "string" ? body : JSON.stringify(body),
    signal,
  });
}

/** Sends a JSON-RPC request with the required `_meta` and headers and collects the response. */
export async function call(
  url: string,
  method: string,
  params: Record<string, any> = {},
  options: CallOptions = {},
): Promise<RpcResponse> {
  const id = options.id ?? nextId++;
  const fullParams = { ...params, _meta: requestMeta(options.capabilities, options.meta) };
  const headers: Record<string, string> = standardHeaders(method, params);
  for (const [k, v] of Object.entries(options.headers ?? {})) {
    for (const existing of Object.keys(headers)) if (existing.toLowerCase() === k.toLowerCase()) delete headers[existing];
    if (v !== null) headers[k] = v;
  }
  const res = await post(url, { jsonrpc: "2.0", id, method, params: fullParams }, headers, options.signal);
  return readResponse(res);
}

export async function readResponse(res: Response): Promise<RpcResponse> {
  const type = res.headers.get("content-type") ?? "";
  if (type.startsWith("text/event-stream")) {
    const messages: any[] = [];
    const stream = new SseReader(res);
    for (;;) {
      const message = await stream.next(30_000);
      if (message === undefined) break;
      messages.push(message);
      if (!("method" in message)) break;
    }
    const body = messages.pop();
    return { status: res.status, headers: res.headers, body, notifications: messages };
  }
  const text = await res.text();
  return { status: res.status, headers: res.headers, body: text ? JSON.parse(text) : undefined, notifications: [] };
}

/** Incremental reader for an SSE response carrying JSON-RPC messages. */
export class SseReader {
  private readonly reader: ReadableStreamDefaultReader<Uint8Array>;
  private readonly decoder = new TextDecoder();
  private buffer = "";
  private readonly queue: any[] = [];
  private done = false;

  constructor(res: Response) {
    this.reader = res.body!.getReader();
  }

  /** Next JSON-RPC message, or undefined when the stream ends. Rejects on timeout. */
  async next(timeoutMs = 5000): Promise<any> {
    const deadline = Date.now() + timeoutMs;
    while (this.queue.length === 0 && !this.done) {
      const remaining = deadline - Date.now();
      if (remaining <= 0) throw new Error("timed out waiting for SSE message");
      let timer: NodeJS.Timeout | undefined;
      const timeout = new Promise<"timeout">((r) => (timer = setTimeout(() => r("timeout"), remaining)));
      const chunk = await Promise.race([this.reader.read(), timeout]);
      clearTimeout(timer);
      if (chunk === "timeout") throw new Error("timed out waiting for SSE message");
      if (chunk.done) {
        this.done = true;
        break;
      }
      this.buffer += this.decoder.decode(chunk.value, { stream: true });
      this.parse();
    }
    return this.queue.shift();
  }

  /** Resolves to true if no message arrives within `ms`. */
  async quiet(ms: number): Promise<boolean> {
    try {
      const message = await this.next(ms);
      if (message !== undefined) this.queue.unshift(message);
      return message === undefined;
    } catch {
      return true;
    }
  }

  async cancel(): Promise<void> {
    await this.reader.cancel().catch(() => {});
  }

  private parse(): void {
    let index: number;
    while ((index = this.buffer.search(/\r?\n\r?\n/)) !== -1) {
      const event = this.buffer.slice(0, index);
      this.buffer = this.buffer.slice(index).replace(/^\r?\n\r?\n/, "");
      const data = event
        .split(/\r?\n/)
        .filter((line) => line.startsWith("data:"))
        .map((line) => line.slice(5).replace(/^ /, ""))
        .join("\n");
      if (data) this.queue.push(JSON.parse(data));
    }
  }
}

/** Opens a subscriptions/listen stream and returns a reader positioned after the response headers. */
export async function listen(url: string, notifications: Record<string, unknown>, id: string | number) {
  const params = { notifications, _meta: requestMeta() };
  const res = await post(url, { jsonrpc: "2.0", id, method: "subscriptions/listen", params }, standardHeaders("subscriptions/listen", params));
  return { res, reader: new SseReader(res) };
}

